sections.text:
template< class T >

using remove_reference_t = typename remove_reference<T>::type;

 (since C++14)

template<class T> struct remove_reference { typedef T type; };
template<class T> struct remove_reference<T&> { typedef T type; };
template<class T> struct remove_reference<T&&> { typedef T type; };

examples.code:
#include <iostream>
#include <type_traits>

int main() {
    std::cout << std::boolalpha;

    std::cout << "std::remove_reference<int>::type is int? "
              << std::is_same<int, std::remove_reference<int>::type>::value << '\n';
    std::cout << "std::remove_reference<int&>::type is int? "
              << std::is_same<int, std::remove_reference<int &>::type>::value << '\n';
    std::cout << "std::remove_reference<int&&>::type is int? "
              << std::is_same<int, std::remove_reference<int &&>::type>::value << '\n';
    std::cout
        << "std::remove_reference<const int&>::type is const int? "
        << std::is_same<const int, std::remove_reference<const int &>::type>::value
        << '\n';
}
